const lead = $('01 - Lead Parser').first().json.output || {};
const company = String(lead.company || '').trim();
const m = company.match(/\(([^)]+)\)/);
const shortName = m ? m[1].trim() : company;
const fullName = company.replace(/\s*\([^)]*\)/g, '').trim() || company;
const country = lead.country || '';
const q = function (s) { return '"' + s + '"'; };
return [{
  json: {
    company: company,
    research_queries: [
      q(fullName) + ' annual report',
      q(shortName) + ' investor relations capex',
      q(shortName) + ' ' + country + ' operations sites',
      q(shortName) + ' Industry 4.0 drone',
      q(shortName) + ' autonomous inspection',
      q(shortName) + ' technology strategy digital transformation',
      q(shortName) + ' recent strategic announcements',
      q(shortName) + ' management operations ' + country
    ]
  }
}];

const results = [];
const errors = [];
for (const item of $input.all()) {
  const r = item.json || {};
  if (r.error) {
    errors.push(String((r.error && r.error.message) || r.error));
    continue;
  }
  const q = (r.search_parameters && r.search_parameters.q) || null;
  const organic = (r.organic_results || []).slice(0, 5);
  for (const o of organic) {
    results.push({
      query: q,
      title: o.title || null,
      url: o.link || null,
      snippet: o.snippet || null,
      source: o.source || null,
      date: o.date || null
    });
  }
}
const seen = {};
const deduped = results.filter(function (x) {
  if (!x.url || seen[x.url]) return false;
  seen[x.url] = true;
  return true;
});
return [{
  json: {
    search_results: deduped,
    result_count: deduped.length,
    search_errors: errors,
    research_status: deduped.length ? 'available' : 'NOT PUBLICLY VERIFIED - no search results returned'
  }
}];

