function parseMaybe(t) {
  if (!t) return null;
  if (typeof t === 'object') return t;
  let s = String(t).trim();
  s = s.replace(/^\x60{3}(?:json)?\s*/i, '').replace(/\x60{3}\s*$/, '');
  try { return JSON.parse(s); } catch (e) { return null; }
}
let pkg = $('16 - Assemble Package').first().json.package || {};
let repaired = false;
try {
  if ($('19 - Repair Output').isExecuted) {
    const p = parseMaybe($('19 - Repair Output').last().json.text);
    if (p) { pkg = p.package || p; repaired = true; }
  }
} catch (e) {}
const v = $input.first().json.output || {};
const status = String(v.status || 'UNKNOWN').toUpperCase();
const finalStatus = status === 'PASS' ? 'PASS' : 'FAIL - NEEDS HUMAN REVIEW';

const L = [];
const list = function (arr) {
  if (!arr || !arr.length) { L.push('- (none)'); return; }
  arr.forEach(function (x) {
    if (x && typeof x === 'object') {
      const text = x.statement || x.claim || x.finding || x.title || x.name || JSON.stringify(x);
      const url = x.source_url || x.url || '';
      const hasSrcField = ('source_url' in x) || ('url' in x);
      L.push('- ' + text + (url ? ' (' + url + ')' : (hasSrcField ? ' (source: NOT PUBLICLY VERIFIED - no public source found)' : '')));
    } else { L.push('- ' + x); }
  });
};
const SENDER = 'Shubham Singh';
if (pkg.response_sequence && Array.isArray(pkg.response_sequence.emails)) {
  pkg.response_sequence.emails.forEach(function (em) {
    if (em && typeof em.body === 'string') em.body = em.body.replace(/\[(your name|name|sender name|your full name)\]/gi, SENDER);
  });
}
if (pkg.account_research && typeof pkg.account_research === 'object') {
  Object.keys(pkg.account_research).forEach(function (sec) {
    const arr = pkg.account_research[sec];
    if (Array.isArray(arr)) arr.forEach(function (it) {
      if (it && typeof it === 'object' && 'source_url' in it && !it.source_url) it.source_url = 'NOT PUBLICLY VERIFIED - no public source found in search results';
    });
  });
}
const q = pkg.qualification || {};
const r = pkg.account_research || {};
const cs = pkg.case_study_match || {};
const gtm = pkg.partner_gtm || {};
const seq = pkg.response_sequence || {};
const ae = pkg.ae_handoff || {};
const lead = pkg.lead || {};

L.push('# FLYTBASE INBOUND BDR - LIVE RUN');
L.push('Lead: ' + (lead.full_name || '') + ' - ' + (lead.job_title || '') + ', ' + (lead.company || ''));
L.push('');
L.push('## 1. Qualification');
L.push('Framework: ' + (q.framework || 'MEDDIC'));
L.push('Score: ' + (q.score != null ? q.score : 'n/a'));
L.push('Priority: ' + (q.priority || 'n/a'));
L.push('### Known');
const k = q.known_information || {};
Object.keys(k).forEach(function (key) {
  const val = Array.isArray(k[key]) ? k[key].join('; ') : k[key];
  L.push('- ' + key + ': ' + (val || 'UNKNOWN'));
});
L.push('### Unknown'); list(q.unknown_information);
L.push('### Discovery Questions'); list(q.discovery_questions);
L.push('');
L.push('## 2. Account Research');
L.push('### Organizational Context'); list(r.organizational_context);
L.push('### Relevant Operations'); list(r.relevant_operations);
L.push('### Budget Signals'); list(r.budget_signals);
L.push('### Technology Investment Signals'); list(r.technology_investment_signals);
L.push('### Strategic Signals'); list(r.recent_strategic_announcements);
L.push('### Operational Priorities'); list(r.operational_priorities);
L.push('### Stakeholders'); list(r.relevant_stakeholders);
L.push('### Implications for FlytBase'); list(r.implications_for_flytbase);
L.push('### Sources'); list(r.sources);
L.push('');
L.push('## 3. Response Sequence');
(seq.emails || []).forEach(function (e) {
  L.push('### Email ' + e.sequence + ': ' + e.subject);
  L.push('Objective: ' + e.objective);
  L.push('Unknowns addressed: ' + (e.unknowns_addressed || []).join('; '));
  L.push('Why now: ' + e.why_now);
  L.push('');
  L.push(e.body);
  L.push('');
});
L.push('Progression: ' + (seq.progression_logic || ''));
L.push('');
L.push('## 4. Case Study / Material Match');
const pc = cs.primary_case_study || {};
L.push('Primary case study: ' + (pc.title || 'n/a') + (pc.url ? ' (' + pc.url + ')' : ''));
L.push('Why: ' + (cs.why_primary_is_best || pc.reason || ''));
const rc = cs.referral_connection || {};
L.push('### Referral connection (' + (rc.referrer || 'referrer') + ')');
L.push('- Lead-stated referral (source: inbound email): ' + (rc.lead_stated_referral || 'n/a'));
L.push('- FlytBase relationship with referrer: ' + ((rc.flytbase_relationship_found !== undefined ? rc.flytbase_relationship_found : rc.found) ? 'DOCUMENTED' : 'NOT FOUND') + ' - ' + (rc.flytbase_relationship_evidence || rc.evidence || '') + (rc.url ? ' (' + rc.url + ')' : ''));
L.push('- Referring contact: ' + (rc.referring_contact_verified ? (rc.referring_contact || '') : 'NOT PUBLICLY VERIFIED - confirm with the lead'));
if (rc.caveat) L.push('- Caveat: ' + rc.caveat);
L.push('### Ranked candidates'); list(cs.ranked_candidates);
L.push('');
L.push('## 5. Partner / GTM');
L.push('Recommended motion: ' + (gtm.recommended_motion || 'n/a'));
const rp = gtm.recommended_partner || {};
L.push('Partner: ' + (rp.name || 'n/a') + ' [' + (rp.status || 'CANDIDATE - UNVERIFIED') + ']' + (rp.url ? ' (' + rp.url + ')' : ''));
if (rp.verified_facts && rp.verified_facts.length) { L.push('Verified facts:'); rp.verified_facts.forEach(function (v) { L.push('- ' + (v.fact || '') + (v.url ? ' (' + v.url + ')' : '')); }); }
if (rp.unverified_assumptions && rp.unverified_assumptions.length) { L.push('Not verified:'); rp.unverified_assumptions.forEach(function (v) { L.push('- ' + v); }); }
if (rp.verification_steps && rp.verification_steps.length) { L.push('Verify before involving partner:'); rp.verification_steps.forEach(function (v) { L.push('- ' + v); }); }
L.push('Reason: ' + (gtm.reasoning || ''));
L.push('### Risks'); list(gtm.risks);
L.push('');
L.push('## 6. AE Handoff');
L.push('Buyer: ' + (ae.buyer_context || ''));
L.push('Opportunity: ' + (ae.opportunity || ''));
L.push('### Top 3 findings'); list(ae.top_3_research_findings);
const rcs = ae.recommended_case_study || {};
L.push('Recommended material: ' + (rcs.title || '') + (rcs.url ? ' (' + rcs.url + ')' : ''));
L.push('GTM motion: ' + (ae.gtm_motion || ''));
L.push('Next step: ' + (ae.suggested_next_step || ''));
L.push('### Discovery questions'); list(ae.discovery_questions);
L.push('### Risks'); list(ae.risks);
L.push('');
L.push('## 7. Validation');
L.push('Status: ' + finalStatus + (repaired ? ' (after one repair pass)' : ''));
L.push('Reason: ' + (v.reason || ''));
if (finalStatus !== 'PASS') {
  L.push('### Needs human review');
  list([].concat(v.unsupported_claims || [], v.missing_sources || [], v.corrections_required || []));
}

return [{ json: { status: finalStatus, repaired: repaired, validation: v, report_markdown: L.join('\n'), result: pkg } }];

